Today, we create zero tensors for non-differentiable outputs in autograd.Function. Also see #98659 (comment)
import torch
import torch._dynamo
from torch.utils._pytree import tree_map

torch.set_default_device('cuda')

def bench(f, name=None, iters=100, warmup=5, display=True, profile=False):
    import time
    from triton.testing import do_bench

    for _ in range(warmup):
        f()
    if profile:
        with torch.profiler.profile() as prof:
            f()
        prof.export_chrome_trace(f"{name if name is not None else 'trace'}.json")

    us_per_iter = do_bench(lambda: f())*1000

    if name is None:
        res = us_per_iter
    else:
        res= f"{name}: {us_per_iter:.3f}us"

    if display:
        print(res)
    return res

@torch.compile
def f(x):
    return x * 2, (x * 3).detach()

inp = torch.randn(2**20, device='cuda', requires_grad=True)
bench(lambda: f(inp)[0].sum().backward(), profile=True)


